CREATE DATABASE IF NOT EXISTS mandisetu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mandisetu;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(140) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('farmer','fpo','buyer','admin','transporter') NOT NULL,phone VARCHAR(35),location VARCHAR(180),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fpos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,registration_ref VARCHAR(120),verification_status ENUM('pending','verified','rejected') DEFAULT 'pending',location VARCHAR(180),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fpo_members(fpo_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,member_since DATE,PRIMARY KEY(fpo_id,user_id),FOREIGN KEY(fpo_id) REFERENCES fpos(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE produce_lots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lot_code VARCHAR(40) UNIQUE NOT NULL,farmer_id BIGINT UNSIGNED NOT NULL,fpo_id BIGINT UNSIGNED,crop_name VARCHAR(100) NOT NULL,variety VARCHAR(100),quantity_quintals DECIMAL(12,2) NOT NULL,ask_price_per_quintal DECIMAL(12,2) NOT NULL,grade VARCHAR(40),harvest_date DATE,location VARCHAR(180),verification_status ENUM('pending','reviewed','verified','rejected') DEFAULT 'pending',status ENUM('available','reserved','sold','withdrawn') DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(farmer_id) REFERENCES users(id),FOREIGN KEY(fpo_id) REFERENCES fpos(id),CHECK(quantity_quintals>0),CHECK(ask_price_per_quintal>0),INDEX idx_lots_crop_status(crop_name,status));
CREATE TABLE quality_checks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lot_id BIGINT UNSIGNED NOT NULL,grader_id BIGINT UNSIGNED,grade VARCHAR(40),moisture_percent DECIMAL(5,2),notes TEXT,evidence_ref VARCHAR(255),status ENUM('pending','passed','failed') DEFAULT 'pending',checked_at TIMESTAMP NULL,FOREIGN KEY(lot_id) REFERENCES produce_lots(id),FOREIGN KEY(grader_id) REFERENCES users(id));
CREATE TABLE market_prices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,commodity VARCHAR(100) NOT NULL,market_name VARCHAR(160) NOT NULL,region VARCHAR(120),price_date DATE NOT NULL,min_price DECIMAL(12,2),modal_price DECIMAL(12,2) NOT NULL,max_price DECIMAL(12,2),source_name VARCHAR(200),source_ref VARCHAR(255),is_sample BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_prices_crop_date(commodity,price_date));
CREATE TABLE price_forecasts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,commodity VARCHAR(100) NOT NULL,market_name VARCHAR(160),forecast_for DATE NOT NULL,lower_estimate DECIMAL(12,2),central_estimate DECIMAL(12,2),upper_estimate DECIMAL(12,2),model_version VARCHAR(80),generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,is_demo BOOLEAN DEFAULT TRUE);
CREATE TABLE buyers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,business_name VARCHAR(180) NOT NULL,buyer_type VARCHAR(80),verification_status ENUM('pending','verified','rejected') DEFAULT 'pending',reliability_score DECIMAL(5,2),score_explanation JSON,completed_orders INT DEFAULT 0,on_time_payments INT DEFAULT 0,cancellations INT DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id),CHECK(reliability_score IS NULL OR reliability_score BETWEEN 0 AND 100));
CREATE TABLE fpo_aggregations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fpo_id BIGINT UNSIGNED NOT NULL,crop_name VARCHAR(100) NOT NULL,total_quantity_quintals DECIMAL(12,2) NOT NULL,target_market VARCHAR(180),status ENUM('draft','open','matched','closed') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(fpo_id) REFERENCES fpos(id),CHECK(total_quantity_quintals>0));
CREATE TABLE aggregation_contributions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,aggregation_id BIGINT UNSIGNED NOT NULL,lot_id BIGINT UNSIGNED NOT NULL,member_user_id BIGINT UNSIGNED NOT NULL,committed_quantity DECIMAL(12,2) NOT NULL,consent_recorded BOOLEAN DEFAULT FALSE,FOREIGN KEY(aggregation_id) REFERENCES fpo_aggregations(id),FOREIGN KEY(lot_id) REFERENCES produce_lots(id),FOREIGN KEY(member_user_id) REFERENCES users(id),CHECK(committed_quantity>0));
CREATE TABLE transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_code VARCHAR(40) UNIQUE NOT NULL,lot_id BIGINT UNSIGNED NOT NULL,buyer_id BIGINT UNSIGNED NOT NULL,farmer_id BIGINT UNSIGNED NOT NULL,quantity_quintals DECIMAL(12,2) NOT NULL,agreed_price_per_quintal DECIMAL(12,2) NOT NULL,status ENUM('requested','confirmed','awaiting_pickup','in_transit','delivered','cancelled') DEFAULT 'requested',payment_status ENUM('pending','paid','refunded','failed','simulated') DEFAULT 'simulated',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(lot_id) REFERENCES produce_lots(id),FOREIGN KEY(buyer_id) REFERENCES users(id),FOREIGN KEY(farmer_id) REFERENCES users(id),CHECK(quantity_quintals>0));
CREATE TABLE cost_estimates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,lot_id BIGINT UNSIGNED,quantity_quintals DECIMAL(12,2) NOT NULL,offer_price_per_quintal DECIMAL(12,2) NOT NULL,transport_cost DECIMAL(12,2) DEFAULT 0,commission_cost DECIMAL(12,2) DEFAULT 0,storage_cost DECIMAL(12,2) DEFAULT 0,other_cost DECIMAL(12,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(lot_id) REFERENCES produce_lots(id));
CREATE TABLE logistics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL,transporter_id BIGINT UNSIGNED,pickup_location VARCHAR(180),delivery_location VARCHAR(180),quoted_cost DECIMAL(12,2),status ENUM('quote_requested','assigned','awaiting_pickup','in_transit','delivered','delayed') DEFAULT 'quote_requested',proof_ref VARCHAR(255),FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(transporter_id) REFERENCES users(id));
CREATE TABLE disputes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL,raised_by BIGINT UNSIGNED NOT NULL,reason VARCHAR(100) NOT NULL,description TEXT,evidence_ref VARCHAR(255),status ENUM('submitted','under_review','awaiting_evidence','resolved','rejected') DEFAULT 'submitted',resolution_note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(raised_by) REFERENCES users(id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id));
-- No real users, buyer verification or price records are seeded. Add approved sample data explicitly for classroom demos.
